import React from 'react';
import { Clock } from 'lucide-react';

const PrayerWidget: React.FC = () => {
  // Simulated dynamic prayer times for Kota Bharu
  const prayerTimes = [
    { name: 'Fajr', time: '06:04 AM' },
    { name: 'Dhuhr', time: '01:21 PM' },
    { name: 'Asr', time: '04:42 PM' },
    { name: 'Maghrib', time: '07:23 PM' },
    { name: 'Isha', time: '08:35 PM' },
  ];

  return (
    <div className="flex items-center gap-4 text-xs lg:text-sm font-medium">
      <div className="flex items-center gap-1.5 opacity-80">
        <Clock className="w-4 h-4" />
        <span className="hidden sm:inline">Kota Bharu:</span>
      </div>
      <div className="flex gap-3 overflow-x-auto no-scrollbar py-1">
        {prayerTimes.map((p) => (
          <div key={p.name} className="flex flex-col sm:flex-row sm:gap-1.5 whitespace-nowrap">
            <span className="font-bold">{p.name}</span>
            <span className="opacity-90">{p.time}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

export default PrayerWidget;

import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Menu, X, Phone, UserRoundSearch, Calendar } from 'lucide-react';
import PrayerWidget from './PrayerWidget';
import { COLORS } from '../constants';

const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const location = useLocation();

  const navLinks = [
    { name: 'Home', path: '/' },
    { name: 'About Us', path: '/about' },
    { name: 'Services', path: '/services' },
    { name: 'Find a Doctor', path: '/find-doctor' },
    { name: 'Patient Guide', path: '/patient-guide' },
  ];

  const isActive = (path: string) => location.pathname === path;

  return (
    <nav className="sticky top-0 z-50 w-full shadow-md bg-white">
      {/* Utility Bar */}
      <div className={`bg-[#006D77] text-white py-2 px-4 md:px-8`}>
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row md:items-center justify-between gap-2">
          <PrayerWidget />
          <div className="flex items-center gap-6 text-sm">
            <a href="tel:+6097477000" className="flex items-center gap-1.5 hover:text-[#83C5BE] transition-colors">
              <Phone className="w-4 h-4" />
              <span>24/7 Emergency: +609 747 7000</span>
            </a>
          </div>
        </div>
      </div>

      {/* Main Nav */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-20">
          <div className="flex items-center">
            <Link to="/" className="flex flex-col leading-tight">
              <span className="text-[#006D77] font-serif text-2xl font-bold tracking-tight">KBMC</span>
              <span className="text-[#2C3E50] text-[10px] uppercase font-bold tracking-widest">Kota Bharu Medical Centre</span>
            </Link>
          </div>

          {/* Desktop Links */}
          <div className="hidden md:flex items-center space-x-8">
            {navLinks.map((link) => (
              <Link
                key={link.name}
                to={link.path}
                className={`text-sm font-semibold tracking-wide transition-colors hover:text-[#006D77] ${
                  isActive(link.path) ? 'text-[#006D77] border-b-2 border-[#006D77]' : 'text-[#2C3E50]'
                }`}
              >
                {link.name}
              </Link>
            ))}
            <Link
              to="/find-doctor"
              className="bg-[#E29578] text-white px-5 py-2.5 rounded-full text-sm font-bold flex items-center gap-2 hover:bg-[#d88466] transition-all transform hover:scale-105"
            >
              <Calendar className="w-4 h-4" />
              Book Appointment
            </Link>
          </div>

          {/* Mobile menu button */}
          <div className="md:hidden flex items-center">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="text-[#2C3E50] hover:text-[#006D77] focus:outline-none"
            >
              {isOpen ? <X className="w-8 h-8" /> : <Menu className="w-8 h-8" />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="md:hidden bg-white border-t border-gray-100">
          <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3">
            {navLinks.map((link) => (
              <Link
                key={link.name}
                to={link.path}
                onClick={() => setIsOpen(false)}
                className={`block px-3 py-2 rounded-md text-base font-medium ${
                  isActive(link.path) ? 'text-[#006D77] bg-gray-50' : 'text-[#2C3E50] hover:bg-gray-50'
                }`}
              >
                {link.name}
              </Link>
            ))}
            <Link
              to="/find-doctor"
              onClick={() => setIsOpen(false)}
              className="block w-full text-center bg-[#E29578] text-white px-3 py-3 rounded-md text-base font-bold mt-4"
            >
              Book an Appointment
            </Link>
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

import React, { useState } from 'react';
import { Search, UserRound, Filter, Star, Calendar, ChevronRight } from 'lucide-react';
import { DOCTORS } from '../constants';

const FindDoctor: React.FC = () => {
  const [filterFemale, setFilterFemale] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const filteredDoctors = DOCTORS.filter((doc) => {
    const matchesGender = filterFemale ? doc.isFemale : true;
    const matchesSearch = doc.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          doc.department.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesGender && matchesSearch;
  });

  return (
    <div className="min-h-screen bg-[#EDF6F9] py-16 px-4 md:px-8">
      <div className="max-w-7xl mx-auto space-y-12">
        <div className="text-center space-y-4">
          <h1 className="text-4xl md:text-5xl font-bold text-[#006D77]">Find Your Specialist</h1>
          <p className="text-gray-600 max-w-2xl mx-auto">
            Choose from over 30 expert consultants across various medical disciplines. 
            Female-led maternity care available upon request.
          </p>
        </div>

        {/* Search & Filter Bar */}
        <div className="bg-white p-6 rounded-3xl shadow-sm flex flex-col md:flex-row gap-6 items-center">
          <div className="relative flex-1 w-full">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
            <input
              type="text"
              placeholder="Search by name, specialty, or condition..."
              className="w-full pl-12 pr-4 py-4 rounded-2xl border border-gray-100 focus:outline-none focus:ring-2 focus:ring-[#006D77] text-lg"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <div className="flex items-center gap-4 w-full md:w-auto">
            <button
              onClick={() => setFilterFemale(!filterFemale)}
              className={`flex items-center gap-2 px-6 py-4 rounded-2xl font-bold transition-all border ${
                filterFemale 
                ? 'bg-[#006D77] text-white border-[#006D77]' 
                : 'bg-white text-[#2C3E50] border-gray-200 hover:border-[#83C5BE]'
              }`}
            >
              <Filter className="w-5 h-5" />
              Female Specialist Only
            </button>
            <button className="bg-[#2C3E50] text-white px-8 py-4 rounded-2xl font-bold hover:bg-[#1a2530] transition-colors flex-1 md:flex-none">
              Search
            </button>
          </div>
        </div>

        {/* Results Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {filteredDoctors.map((doc) => (
            <div key={doc.id} className="bg-white rounded-[2.5rem] overflow-hidden shadow-sm hover:shadow-xl transition-all border border-transparent hover:border-[#83C5BE]">
              <div className="relative h-64 overflow-hidden">
                <img src={doc.imageUrl} alt={doc.name} className="w-full h-full object-cover" />
                <div className="absolute top-4 right-4 bg-white/90 backdrop-blur px-4 py-1.5 rounded-full text-xs font-bold text-[#006D77] flex items-center gap-1">
                  <Star className="w-3 h-3 fill-current" />
                  Highly Recommended
                </div>
              </div>
              <div className="p-8 space-y-6">
                <div className="space-y-1">
                  <h3 className="text-2xl font-bold text-[#006D77]">{doc.name}</h3>
                  <p className="text-[#E29578] font-bold text-sm tracking-widest uppercase">{doc.designation}</p>
                </div>

                <p className="text-gray-600 text-sm line-clamp-3">
                  {doc.bio}
                </p>

                <div className="space-y-3">
                  <p className="text-xs font-bold uppercase tracking-widest text-gray-400">Clinical Focus</p>
                  <div className="flex flex-wrap gap-2">
                    {doc.focus.map((f) => (
                      <span key={f} className="bg-[#EDF6F9] text-[#006D77] px-3 py-1 rounded-full text-xs font-semibold">
                        {f}
                      </span>
                    ))}
                  </div>
                </div>

                <div className="pt-6 border-t border-gray-100 flex gap-3">
                  <button className="flex-1 bg-[#E29578] text-white py-4 rounded-2xl font-bold text-sm flex items-center justify-center gap-2 hover:bg-[#d88466] transition-colors">
                    <Calendar className="w-4 h-4" />
                    Book Now
                  </button>
                  <button className="px-4 py-4 rounded-2xl border border-gray-200 hover:bg-gray-50 transition-colors">
                    <ChevronRight className="w-5 h-5 text-gray-400" />
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>

        {filteredDoctors.length === 0 && (
          <div className="text-center py-24 bg-white rounded-3xl space-y-4">
            <UserRound className="w-16 h-16 text-gray-200 mx-auto" />
            <h3 className="text-2xl font-bold text-gray-400">No Specialists Found</h3>
            <p className="text-gray-500">Try adjusting your filters or search keywords.</p>
            <button 
              onClick={() => {setSearchQuery(''); setFilterFemale(false);}}
              className="text-[#006D77] font-bold underline"
            >
              Clear all filters
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default FindDoctor;

