import React, { useState, useEffect } from 'react';
import { Search, UserRound, Filter, Star, Calendar, ChevronRight, UserCircle2 } from 'lucide-react';
import { DOCTORS } from '../constants';

const FindDoctor: React.FC = () => {
  const [filterFemale, setFilterFemale] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    setIsVisible(true);
  }, []);

  const filteredDoctors = DOCTORS.filter((doc) => {
    const matchesGender = filterFemale ? doc.isFemale : true;
    const matchesSearch = doc.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          doc.department.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesGender && matchesSearch;
  });

  return (
    <div className="min-h-screen bg-[#F8FAFB] py-32 px-4 md:px-8 overflow-hidden">
      <div className="max-w-7xl mx-auto space-y-20 relative">
        <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-[#006D77]/5 rounded-full blur-[120px] -z-10 translate-x-1/2"></div>

        <div className={`text-center space-y-8 ${isVisible ? 'animate-fade-in-up' : 'opacity-0'}`}>
          <span className="text-[#83C5BE] font-black uppercase tracking-[0.4em] text-sm">Medical Registry</span>
          <h1 className="text-6xl md:text-8xl font-black text-[#006D77] leading-[1.1]">Elite <br/><span className="text-[#E29578] italic">Specialists.</span></h1>
          <p className="text-xl md:text-2xl text-gray-500 max-w-2xl mx-auto font-medium leading-relaxed">
            Connect with over 30 board-certified consultants. We provide specialized care with respect to cultural and religious preferences.
          </p>
        </div>

        {/* Search & Filter Bar with Modern Glassmorphism */}
        <div className={`glass-nav p-8 md:p-12 rounded-[4rem] shadow-2xl border border-white flex flex-col md:flex-row gap-8 items-center relative z-20 ${isVisible ? 'animate-fade-in-up stagger-1' : 'opacity-0'}`}>
          <div className="relative flex-1 w-full group">
            <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-[#006D77] transition-colors" />
            <input
              type="text"
              placeholder="Search by name, department, or clinical interest..."
              className="w-full pl-16 pr-6 py-6 rounded-3xl border-2 border-transparent bg-white/50 focus:bg-white focus:outline-none focus:border-[#006D77]/20 transition-all text-xl font-medium placeholder:text-gray-300 shadow-inner"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <div className="flex items-center gap-6 w-full md:w-auto">
            <button
              onClick={() => setFilterFemale(!filterFemale)}
              className={`flex items-center gap-3 px-10 py-6 rounded-3xl font-black text-sm uppercase tracking-widest transition-all border-2 active:scale-95 whitespace-nowrap ${
