      title: "Advanced Surgical Theaters",
      testimonial: "World-class facilities right here in Kota Bharu. The precision and care shown by the surgical team were exceptional.",
      author: "Encik Ahmad Fauzi",
      role: "Orthopedic Patient"
    },
    {
      image: "https://images.unsplash.com/photo-1502740479091-635887520276?q=80&w=2069&auto=format&fit=crop",
      title: "Diagnostic Imaging Center",
      testimonial: "Efficient, clean, and professional. The high-tech MRI imaging and quick results gave me the peace of mind I needed.",
      author: "Dato' Wong",
      role: "Health Screening Patient"
    },
    {
