import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { MessageSquare, X, Send, Bot, User, Sparkles, Loader2, Minus } from 'lucide-react';

interface Message {
  role: 'user' | 'model';
  text: string;
}

const AIChatbot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: 'Selamat Sejahtera! I am your KBMC Virtual Assistant. How can I help you with our services, specialists, or admission procedures today?' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Listen for global open event
  useEffect(() => {
    const handleOpenChat = (e: any) => {
      setIsOpen(true);
      if (e.detail?.initialMessage) {
        setInput(e.detail.initialMessage);
      }
    };
    window.addEventListener('kbmc-open-chat', handleOpenChat);
    return () => window.removeEventListener('kbmc-open-chat', handleOpenChat);
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSendMessage = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const chat = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
          systemInstruction: `You are the KBMC (Kota Bharu Medical Centre) Virtual Assistant. 
          Your goal is to assist patients and visitors with information about the hospital. 
          Key info: 
          - Located in Lundang, Kota Bharu. 
          - Specialists include Dr. Muspirah Zakaria (Ortho), Dr. Norhaira Mohamed Noor (O&G), and Dr. Mohd Rizal (Paeds). 
          - Services: O&G, Ortho, Paeds, Surgery, Medicine, Diagnostics (MRI/CT). 
          - Admission: Need National ID/MyKad, Guarantee Letter (GL), medical records. 
          - Shariah-compliant and Ibadah-friendly environment.
          Tone: Professional, compassionate, and helpful. 
          Disclaimer: Always mention you provide general information and not direct medical advice.`,
        },
      });

      const responseStream = await chat.sendMessageStream({ message: userMessage });

      let fullResponse = "";
      setMessages(prev => [...prev, { role: 'model', text: "" }]);

      for await (const chunk of responseStream) {
        const textChunk = chunk.text;
        fullResponse += textChunk;
        setMessages(prev => {
          const newMessages = [...prev];
          newMessages[newMessages.length - 1].text = fullResponse;
          return newMessages;
        });
      }
    } catch (error) {
      console.error("Chatbot Error:", error);
      setMessages(prev => [...prev, { role: 'model', text: "I apologize, but I'm having trouble connecting right now. Please try again or call our hotline at +609 747 7000." }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed bottom-8 right-8 z-[200] flex flex-col items-end">
      {/* Chat Window */}
      {isOpen && (
        <div className="mb-6 w-[90vw] sm:w-[400px] h-[600px] bg-white/90 backdrop-blur-2xl rounded-[3rem] shadow-[0_50px_100px_-20px_rgba(0,109,119,0.3)] border border-white flex flex-col overflow-hidden animate-in slide-in-from-bottom-10 fade-in duration-500">
          {/* Header */}
          <div className="bg-[#006D77] p-8 text-white flex justify-between items-center relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -translate-y-1/2 translate-x-1/2"></div>
            <div className="flex items-center gap-4 relative z-10">
              <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center backdrop-blur-md">
                <Bot className="w-7 h-7" />
              </div>
              <div>
                <h3 className="font-black text-lg leading-tight">KBMC Assistant</h3>
                <div className="flex items-center gap-2">
                  <span className="w-2 h-2 rounded-full bg-[#83C5BE] animate-pulse"></span>
                  <span className="text-[10px] uppercase font-black tracking-widest opacity-70">AI Powered</span>
                </div>
              </div>
            </div>
            <button 
              onClick={() => setIsOpen(false)}
              className="p-2 hover:bg-white/10 rounded-xl transition-colors relative z-10"
            >
              <Minus className="w-6 h-6" />
            </button>
          </div>

          {/* Messages Area */}
          <div 
            ref={scrollRef}
            className="flex-grow p-8 overflow-y-auto no-scrollbar space-y-6"
          >
            {messages.map((msg, idx) => (
              <div 
                key={idx} 
                className={`flex gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : ''} animate-in fade-in slide-in-from-bottom-2`}
              >
                <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 shadow-sm ${msg.role === 'user' ? 'bg-[#E29578] text-white' : 'bg-[#EDF6F9] text-[#006D77]'}`}>
                  {msg.role === 'user' ? <User className="w-5 h-5" /> : <Sparkles className="w-5 h-5" />}
                </div>
                <div className={`max-w-[80%] p-5 rounded-[2rem] text-sm font-medium leading-relaxed shadow-sm ${msg.role === 'user' ? 'bg-[#006D77] text-white rounded-tr-none' : 'bg-[#F8FAFB] text-[#2C3E50] rounded-tl-none border border-gray-100'}`}>
                  {msg.text || (isLoading && idx === messages.length - 1 ? <Loader2 className="w-4 h-4 animate-spin opacity-50" /> : '')}
                </div>
              </div>
            ))}
            {isLoading && messages[messages.length-1].role === 'user' && (
              <div className="flex gap-4 animate-in fade-in">
                <div className="w-10 h-10 rounded-xl bg-[#EDF6F9] text-[#006D77] flex items-center justify-center shrink-0">
                  <Sparkles className="w-5 h-5 animate-pulse" />
                </div>
                <div className="bg-[#F8FAFB] p-5 rounded-[2rem] rounded-tl-none border border-gray-100 flex items-center gap-2">
                  <span className="w-1.5 h-1.5 bg-[#83C5BE] rounded-full animate-bounce"></span>
                  <span className="w-1.5 h-1.5 bg-[#83C5BE] rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  <span className="w-1.5 h-1.5 bg-[#83C5BE] rounded-full animate-bounce [animation-delay:0.4s]"></span>
                </div>
              </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-8 border-t border-gray-50 bg-white">
            <div className="relative group">
              <input 
                type="text"
                placeholder="Ask me anything..."
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                className="w-full pl-6 pr-20 py-5 rounded-[2rem] bg-[#F8FAFB] border-2 border-transparent focus:border-[#006D77]/20 focus:bg-white outline-none transition-all font-bold text-sm"
              />
              <button 
                onClick={handleSendMessage}
                disabled={!input.trim() || isLoading}
                className="absolute right-2 top-2 bottom-2 px-6 bg-[#006D77] text-white rounded-[1.5rem] flex items-center justify-center hover:bg-[#E29578] transition-all disabled:opacity-50 active:scale-95"
              >
                <Send className="w-5 h-5" />
              </button>
            </div>
            <p className="text-[10px] text-gray-300 text-center mt-4 font-bold uppercase tracking-widest">General info only • Not medical advice</p>
          </div>
        </div>
      )}

      {/* Toggle Button */}
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`w-20 h-20 rounded-[2rem] flex items-center justify-center shadow-[0_20px_50px_rgba(0,109,119,0.4)] transition-all duration-500 hover:scale-110 active:scale-95 relative group ${isOpen ? 'bg-[#2C3E50] rotate-90' : 'bg-[#006D77]'}`}
      >
        {!isOpen && (
          <div className="absolute -inset-2 bg-[#006D77] rounded-[2rem] animate-ping opacity-20"></div>
        )}
        {isOpen ? (
          <X className="w-10 h-10 text-white" />
        ) : (
          <MessageSquare className="w-10 h-10 text-white group-hover:animate-bounce" />
        )}
        {!isOpen && (
          <div className="absolute -top-2 -right-2 w-6 h-6 bg-[#E29578] rounded-full border-4 border-white flex items-center justify-center animate-bounce">
            <Sparkles className="w-3 h-3 text-white" />
          </div>
        )}
      </button>
    </div>
  );
};

export default AIChatbot;

