              className="w-16 h-16 rounded-full bg-white/10 backdrop-blur-xl border border-white/20 flex items-center justify-center text-white hover:bg-white hover:text-[#006D77] transition-all transform hover:scale-110 active:scale-90"
            >
              <ChevronLeft className="w-8 h-8" />
            </button>
            <button 
              onClick={handleNext}
              className="w-16 h-16 rounded-full bg-white/10 backdrop-blur-xl border border-white/20 flex items-center justify-center text-white hover:bg-white hover:text-[#006D77] transition-all transform hover:scale-110 active:scale-90"
            >
