            </button>
          </div>

          {/* Indicators */}
          <div className="absolute bottom-12 left-12 flex gap-3 z-20">
            {slides.map((_, i) => (
              <button
                key={i}
                onClick={() => setCurrent(i)}
                className={`h-2 rounded-full transition-all duration-500 ${current === i ? 'w-12 bg-white' : 'w-3 bg-white/30'}`}
              />
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

